---@class ActivityMidFestivalBossTool
local ActivityMidFestivalBossTool = {}

function ActivityMidFestivalBossTool.BossHomeReq()
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    ---@type ActivityMidFestivalBossComponent
    local bossComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalBossComponent)

    local activityId = activityComp:GetActivityDojo().id

    GameUtils.Request(Interfaces.OverseaMidFestivalBossHome, { activityUuid = activityId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            Events.Broadcast(Constants.EventNames.MidFestivalBossHomeReq)
            return
        end
        local jsonData = response.data
        bossComp:GetBossHomeDojo():Fill(jsonData)
        Events.Broadcast(Constants.EventNames.MidFestivalBossHomeReq)
    end)
end

---DrawRewardReq 领取伤害奖励，rewardId为nil表示一键领取
function ActivityMidFestivalBossTool.DrawRewardReq(rewardId)

    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    ---@type ActivityMidFestivalBossComponent
    local bossComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalBossComponent)

    local req = {
        activityUuid = activityComp:GetActivityDojo().id,
        rewardId = rewardId
    }
    GameUtils.Request(Interfaces.OverseaMidFestivalBossDrawHurtReward, req, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards

        bossComp:GetBossHomeDojo():DrawReward(rewardId)

        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end

        Events.Broadcast(Constants.EventNames.ActivityMidFestivalBossDamageRewardDraw)
    end)
end

return ActivityMidFestivalBossTool
